import { test, expect, Page } from '@playwright/test';

test.describe('Form Submission Success Feedback', () => {
  let page: Page;

  test.beforeEach(async ({ browser }) => {
    page = await browser.newPage();
    await page.goto('data:text/html,<html><body><form id="testForm"><label for="name">Name:</label><input id="name" type="text" required /><label for="email">Email:</label><input id="email" type="email" required /><label for="message">Message:</label><textarea id="message" required></textarea><button type="submit">Submit</button></form><div id="successMessage" style="display:none;color:green;margin-top:10px;"><strong>Success!</strong> Your form has been submitted successfully.</div><div id="errorMessage" style="display:none;color:red;margin-top:10px;"></div><script>document.getElementById("testForm").addEventListener("submit", function(e) { e.preventDefault(); const name = document.getElementById("name").value; const email = document.getElementById("email").value; const message = document.getElementById("message").value; const errorDiv = document.getElementById("errorMessage"); errorDiv.style.display = "none"; if (!name || !email || !message) { errorDiv.textContent = "All fields are required"; errorDiv.style.display = "block"; return; } if (!email.includes("@")) { errorDiv.textContent = "Invalid email format"; errorDiv.style.display = "block"; return; } document.getElementById("successMessage").style.display = "block"; document.getElementById("testForm").reset(); });</script></body></html>');
  });

  test('should display success message after valid form submission', async () => {
    const nameInput = page.getByLabel('Name:');
    const emailInput = page.getByLabel('Email:');
    const messageInput = page.getByLabel('Message:');
    const submitButton = page.getByRole('button', { name: 'Submit' });
    const successMessage = page.locator('#successMessage');

    await nameInput.fill('John Doe');
    await emailInput.fill('john@example.com');
    await messageInput.fill('This is a test message');

    await submitButton.click();

    await expect(successMessage).toBeVisible();
    await expect(successMessage).toContainText('Success!');
    await expect(successMessage).toContainText('Your form has been submitted successfully');
  });

  test('should clear form fields after successful submission', async () => {
    const nameInput = page.getByLabel('Name:');
    const emailInput = page.getByLabel('Email:');
    const messageInput = page.getByLabel('Message:');
    const submitButton = page.getByRole('button', { name: 'Submit' });

    await nameInput.fill('Jane Smith');
    await emailInput.fill('jane@example.com');
    await messageInput.fill('Another test message');

    await submitButton.click();

    await expect(nameInput).toHaveValue('');
    await expect(emailInput).toHaveValue('');
    await expect(messageInput).toHaveValue('');
  });

  test('should not display success message when form submission fails due to missing fields', async () => {
    const submitButton = page.getByRole('button', { name: 'Submit' });
    const successMessage = page.locator('#successMessage');
    const errorMessage = page.locator('#errorMessage');

    await submitButton.click();

    await expect(successMessage).not.toBeVisible();
    await expect(errorMessage).toBeVisible();
    await expect(errorMessage).toContainText('All fields are required');
  });

  test('should not display success message when email format is invalid', async () => {
    const nameInput = page.getByLabel('Name:');
    const emailInput = page.getByLabel('Email:');
    const messageInput = page.getByLabel('Message:');
    const submitButton = page.getByRole('button', { name: 'Submit' });
    const successMessage = page.locator('#successMessage');
    const errorMessage = page.locator('#errorMessage');

    await nameInput.fill('John Doe');
    await emailInput.fill('invalid-email');
    await messageInput.fill('Test message');

    await submitButton.click();

    await expect(successMessage).not.toBeVisible();
    await expect(errorMessage).toBeVisible();
    await expect(errorMessage).toContainText('Invalid email format');
  });

  test('should display success message with correct styling', async () => {
    const nameInput = page.getByLabel('Name:');
    const emailInput = page.getByLabel('Email:');
    const messageInput = page.getByLabel('Message:');
    const submitButton = page.getByRole('button', { name: 'Submit' });
    const successMessage = page.locator('#successMessage');

    await nameInput.fill('Test User');
    await emailInput.fill('test@example.com');
    await messageInput.fill('Testing success feedback');

    await submitButton.click();

    const computedStyle = await successMessage.evaluate((el) => {
      return window.getComputedStyle(el);
    });

    expect(computedStyle.display).not.toBe('none');
    expect(computedStyle.color).toContain('green');
  });

  test('should hide error message when form is successfully submitted after previous error', async () => {
    const nameInput = page.getByLabel('Name:');
    const emailInput = page.getByLabel('Email:');
    const messageInput = page.getByLabel('Message:');
    const submitButton = page.getByRole('button', { name: 'Submit' });
    const errorMessage = page.locator('#errorMessage');
    const successMessage = page.locator('#successMessage');

    // First submission with invalid data
    await nameInput.fill('John');
    await emailInput.fill('invalid');
    await messageInput.fill('Message');
    await submitButton.click();

    await expect(errorMessage).toBeVisible();
    await expect(errorMessage).toContainText('Invalid email format');

    // Clear and submit with valid data
    await nameInput.clear();
    await emailInput.clear();
    await messageInput.clear();

    await nameInput.fill('John Doe');
    await emailInput.fill('john@example.com');
    await messageInput.fill('Valid message');
    await submitButton.click();

    await expect(errorMessage).not.toBeVisible();
    await expect(successMessage).toBeVisible();
  });
});
